-- Fix MS ITM and MS Marketing core courses (bad JSON data corrected from XLSX)

-- ── MS ITM ──────────────────────────────────────────
DELETE FROM program_core_courses WHERE program_id = '41ca0bd8-3ace-c12c-2eb8-ec90f2c7423c';
UPDATE programs SET num_core_courses=6 WHERE id='41ca0bd8-3ace-c12c-2eb8-ec90f2c7423c';

-- ── MS Marketing ──────────────────────────────────────────
DELETE FROM program_core_courses WHERE program_id = '8c02c99b-6e89-779a-b7d9-dd583c3b6b3b';
UPDATE programs SET num_core_courses=5 WHERE id='8c02c99b-6e89-779a-b7d9-dd583c3b6b3b';

-- Verify
SELECT p.program_name, p.num_core_courses, COUNT(DISTINCT pcc.id) as rows, COUNT(DISTINCT CASE WHEN pcc.or_group_id>0 THEN pcc.or_group_id END) as or_groups
FROM programs p JOIN program_core_courses pcc ON pcc.program_id=p.id
WHERE p.program_name IN ('Master of Science in Information Technology and Management','Master of Science in Marketing')
GROUP BY p.program_name, p.num_core_courses;